import{_ as s,l as i,o as a,c as l,v as t,p as c,x as r,d,i as n,S as u}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"futex","description":"","frontmatter":{"title":"futex","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/futex.md","filePath":"cs/futex.md","lastUpdated":1789023840000}'),f={name:"cs/futex.md"};function p(h,e,x,m,_,A){const o=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="futex" tabindex="-1">futex <a class="header-anchor" href="#futex" aria-label="Permalink to &quot;futex&quot;">​</a></h1><div class="epigraph"><p>未争用时用户用原子指令改一个对齐的整字；只有需要睡眠或唤醒时才陷入内核——这就是快速用户空间互斥。</p><footer>—— 据 Franke, Russell and Kirkwood, Fuss, Futexes and Furwocks；Love, LKD 整理</footer></div><p><a href="/cs/mutex-sleep">上一课</a>的内核 mutex 每次获取都在内核对象上转。用户进程有自己的锁字，若无争用不应付<a href="/cs/syscall-path">系统调用路径</a>的税。缺口是 <strong>futex</strong>：用户地址上的整数 + 内核里按该地址排队的等待者。本课钉未争用快路径与陷入慢路径，不写全部操作码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯用户自旋：持有者被切走则空转。纯系统调用锁：未争用也陷入。futex：<code>cmpxchg</code> 把字从 0 改成 1 即得锁；失败则 <code>FUTEX_WAIT</code> 把当前线程挂到该用户地址对应的内核队列上。释放：用户把字清 0，若可能有等待者则 <code>FUTEX_WAKE</code>。缺口不是再定义所有者——用户库可在字旁另存 tid——而是<strong>内核只介入睡眠</strong>。</p><p><span class="marginnote">等待队列键是「这块内存」：进程私有 futex 用 mm+地址；共享 futex 用 inode 或文件映射，使进程间锁成为可能。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>库：未争用 TAS/CAS；争用则 wait。内核：校验用户地址可写，把任务挂到哈希到该 futex 的队列，睡眠。wake：找到队列唤醒 n 个。与<a href="/cs/restart-syscall">重启系统调用</a>：wait 可被信号打断。PI futex 把所有者 tid 写进字里，供内核 boost，对接<a href="/cs/pi-pcp">PI</a>。</p>',8)),(a(),c(u,null,{default:r(()=>[n(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAST%5B%22%E7%94%A8%E6%88%B7%20CAS%20%E6%88%90%E5%8A%9F%22%5D%20--%3E%20HOLD%5B%22%E6%9C%AA%E9%99%B7%E5%85%A5%22%5D%0A%20%20SLOW%5B%22CAS%20%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20WAIT%5B%22futex%20wait%20%E7%9D%A1%E7%9C%A0%22%5D%0A%20%20UN%5B%22%E7%94%A8%E6%88%B7%E6%B8%85%E9%94%81%E5%AD%97%22%5D%20--%3E%20WAKE%5B%22%E5%BF%85%E8%A6%81%E6%97%B6%20futex%20wake%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>不要在内核里解释锁的高层语义；内核只卖睡眠与唤醒。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>futex 把<a href="/cs/race-critical">临界区</a> 的实现拆成用户原子 + 内核等待队列。未争用路径无陷入、无内核锁对象泄漏。进程退出时内核要清理该任务挂过的 futex 等待，以免幽灵唤醒。与<a href="/cs/copy-from-user">copy_from_user</a> 不同，锁字就在用户页上，内核用原子访问那一页，仍须防缺页与卸载。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 <code>FUTEX_*</code> 命令当手册，不讨论如何用错误的 wake 做拒绝服务细节。条件变量可用 futex 做等待队列，完整管程在已有课。下一课把「多人只读、一人写」做成 rwlock。</p><p>后课默认：用户锁未争用走原子，争用走 futex。读多写少时一把互斥太粗，下一课读写锁。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>futex：用户字上的快路径 + 内核按地址睡眠。</li><li>内核不管锁语义，只 wait/wake。</li><li>读写锁是下一课。</li><li>出处：Franke et al., <em>Ottawa Linux Symposium</em>；Love, <em>LKD</em>。</li></ul>',8))])}const k=s(f,[["render",p]]);export{T as __pageData,k as default};
